            <button
              key={box.corner}
              type="button"
              className="assistant-corner"
              data-corner={box.corner}
              aria-label={`Resize from the ${CORNER_LABEL[box.corner]} corner`}
              title="Drag to resize · arrow keys resize · Home resets"
