              onPointerMove={panel.pointerMove}
              onPointerUp={panel.pointerUp}
              onPointerCancel={panel.pointerUp}
              onLostPointerCapture={panel.pointerUp}
              onKeyDown={(e) => panel.keyboard(e, box.corner)}
            />
